window.products.push({"id":186824,"name":"Kenney KN75351 Seville 5/8\" Standard Decorative Window Curtain Rod, 48-86\", Oil Rubbed Bronze","category":"homeandappliances","retail price":21.99,"sale price":null,"image":"https://m.media-amazon.com/images/I/71mQVLYsYcL._AC_SL1500_.jpg","description":"Add a touch of style to your home with the Seville Standard Decorative Window Curtain Rod by Kenney. The 5/8 inch diameter Seville curtain rod in oil rubbed bronze features matching square finial ends. Use in your kitchen, bedroom, dining room, and living room to hang light to medium weight curtains. The telescoping rod adjusts from 48 inches to 86 inches to fit your window and projects 3 inches from the wall. It is ideal for hanging curtains with pockets, grommets, back tabs, and tab tops, but can also be used with clip rings. Drapery Hardware Set Includes: one telescoping steel curtain rod with decorative square finials (2.64\" L x 2.23\" W x 2.23\" H), two mounting brackets, one center support, screws, drywall anchors, and installation instructions.","images":["https://m.media-amazon.com/images/I/71mQVLYsYcL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/61zNIJh6ZCL._SL1500_.jpg","https://m.media-amazon.com/images/I/61TWUez1VxL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/51TIpnkrEpL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/51I6jTu8yCL._AC_SL1300_.jpg","https://m.media-amazon.com/images/I/31o9GyU6jnL._AC_.jpg"],"specifications":{"brand":"Kenney","source_asin":"B0C4ZTX16X","category_path":"Home & Kitchen"},"sku":"BM-186824","productType":"Home & Appliances","inventory":0,"age_group":"Adult","gender":"Unisex","source_url":"https://www.amazon.com/dp/B0C4ZTX16X","source_catalog":"Amazon Reviews 2023 product metadata","source_file":"meta_Home_and_Kitchen_2023.jsonl","source_asin":"B0C4ZTX16X","price_pending":true,"merchant_ready":false});
